/**
 * OmniPulse Full-Stack Server (Vercel + Render + Localhost Compatible)
 * Fixes "Cannot GET /" on Vercel by:
 * 1. Handling GET / explicitly and serving the full OmniPulse dashboard HTML
 * 2. Exporting module.exports = app for Vercel Serverless Functions
 */
require('dotenv').config();
const express = require('express');
const cors = require('cors');
const fs = require('fs');
const path = require('path');
const { createClient } = require('@supabase/supabase-js');

const app = express();
const PORT = process.env.PORT || 3000;
const VERIFY_TOKEN = process.env.VERIFY_TOKEN || 'omnipulse_secret_verify_token_2026';

const supabase = (process.env.SUPABASE_URL && process.env.SUPABASE_SERVICE_KEY)
  ? createClient(process.env.SUPABASE_URL, process.env.SUPABASE_SERVICE_KEY)
  : null;

app.use(cors());
app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));
app.use(express.static(__dirname));

